FROM bus_route
WHERE ROUTE_NO IN ('111','1114','1115','112','1134','114','1144','115','1154','118','121','1214','122','1224','123','1234','124','126','128','132','134','1411','1413','142','1421','1432','1452','1462','1713','1715','1723','1733','213','215','216','217','219','225','226','236','246','313','314','318','323','333','343','353','363','373','383','412','413','414','415','416','417','418','422','423','428','432','438','442','452','462','472','482','492','5001','5002','5003','5004','5005','513','514','515','518','523','533','543','5801','5901','6011','6012','6021','6022','6031','6032','6101','6102','6103','6104','6151','6152','6153','6154','6155','6156','6157','6201','6202','6203','6204','6205','6206','6207','6208','6209','6210','6211','6212','6213','6214','6215','6249','6251','6252','6301','6302','6303','6351','6352','6353','6354','6401','6402','6403','6404','6405','6406','6407','6408','6409','6410','6411','6412','6413','6451','6452','6453','6454','6461','6462','6463','6464','6481','6482','6483','6484','6485','6486','6487','6488','6489','6490','6501','6502','6503','6504','6505','6506','6507','6508','6509','6510','6511','6513','711','712','713','714','715','716','718','721','722','723','724','725','728','731','732','734','735','741','742','743','744','752','753','754','762','763','772','773','918');
